# Code vendored from pecotmr commit 79287d5 (closure of: filterVariantsByLdReference, parseVariantId).
# Generated by migration_test/scripts/vendor_pecotmr.R; copied as-is apart from dropped
# roxygen comments. Evaluated by .onLoad into a private environment (see zzz.R) so
# these names never mask qQTLR or pecotmr bindings.

.pecotmr_legacy_ld_defs <- function() {
  # ---- .dosageMatrix (pecotmr R/genotypeIo.R)
  .dosageMatrix <- function(handle, snpIdx, meanImpute = TRUE) {
    t(SummarizedExperiment::assay(
      extractBlockGenotypes(handle, snpIdx, meanImpute = meanImpute), "dosage"))
  }

  # ---- .extractBlockForChrom (pecotmr R/genotypeIo.R)
  .extractBlockForChrom <- function(chrom, posInReq, handle, snpIdx, unifiedChr, meanImpute) {
    if (!chrom %in% names(handle@chromPaths))
      stop("extractBlockGenotypes: no per-chromosome file for chromosome '",
           chrom, "' (have: ",
           paste(names(handle@chromPaths), collapse = ", "), ").")
    blockGlobal <- which(unifiedChr == chrom)        # file-order global indices
    localIdx    <- match(snpIdx[posInReq], blockGlobal)
    th <- handle
    th@path       <- handle@chromPaths[[chrom]]
    th@snpInfo    <- handle@snpInfo[blockGlobal, , drop = FALSE]
    th@pgenPtr    <- NULL
    th@chromPaths <- character(0)                     # treat as single-file
    extractBlockGenotypes(th, localIdx, meanImpute = meanImpute)
  }

  # ---- .extractBlockGds (pecotmr R/genotypeIo.R)
  .extractBlockGds <- function(handle, snpIdx) {
    .withGds(.genotypeReadPath(handle), allow.fork = TRUE, fn = function(gds) {
      snpIds <- getSnpInfo(handle)$SNP[snpIdx]
      # Use snpgdsGetGeno for proper non-contiguous SNP selection
      geno <- SNPRelate::snpgdsGetGeno(gds, snp.id = snpIds,
                                       with.id = FALSE, verbose = FALSE)
      if (is.null(geno) || length(geno) == 0) return(NULL)
      # snpgdsGetGeno returns count of the first allele in snp.allele,
      # which we label A1 in .gdsSnpInfo. No flip needed.
      storage.mode(geno) <- "double"
      geno
    })
  }

  # ---- .extractBlockPlink1 (pecotmr R/genotypeIo.R)
  .extractBlockPlink1 <- function(handle, snpIdx) {
    snpIds <- getSnpInfo(handle)$SNP[snpIdx]
    pathStem <- .genotypeReadPath(handle)
    plinkData <- snpStats::read.plink(
      bed = paste0(pathStem, ".bed"),
      bim = paste0(pathStem, ".bim"),
      fam = paste0(pathStem, ".fam"),
      select.snps = snpIds
    )
    # snpStats as(x, "numeric") gives count of B allele (A2/bim col 6).
    # Flip to count A1 (bim col 5 / effect allele).
    geno <- 2 - as(plinkData$genotypes, "numeric")
    storage.mode(geno) <- "double"
    geno
  }

  # ---- .extractBlockPlink2 (pecotmr R/genotypeIo.R)
  .extractBlockPlink2 <- function(handle, snpIdx) {
    # pgenlibr::ReadList returns ALT dosage = A1 dosage in pecotmr convention.
    # The cached @pgenPtr does not survive saveRDS/readRDS (external pointers
    # become stale), so we re-open from getPath() on the fly if the cached
    # pointer errors out. Opening is cheap relative to dosage extraction.
    ptr <- getPgenPtr(handle)
    paths <- resolvePlink2Paths(.genotypeReadPath(handle))
    # `variant_subset` indexes the .pgen by FILE position. `snpIdx` is a position
    # into @snpInfo, which may have been row-subset; translate through fileIdx to
    # recover the true .pgen index. For a full handle fileIdx == seq_len(nrow), so
    # this is a no-op. Older RDS handles predate the column -> fall back to snpIdx.
    fileIdx <- getSnpInfo(handle)$fileIdx
    variantSubset <- if (is.null(fileIdx)) snpIdx else fileIdx[snpIdx]
    # A sharded handle routes through a transient view with pgenPtr = NULL (one
    # pgen per chromosome), and a deserialized pointer is stale; open a fresh
    # pgen up front in those cases rather than provoking a caught read error.
    if (is.null(ptr)) ptr <- pgenlibr::NewPgen(paths$pgen)
    geno <- tryCatch(
      pgenlibr::ReadList(ptr, variant_subset = variantSubset, meanimpute = FALSE),
      error = function(e) {
        reopened <- pgenlibr::NewPgen(paths$pgen)
        pgenlibr::ReadList(reopened, variant_subset = variantSubset, meanimpute = FALSE)
      })
    storage.mode(geno) <- "double"
    geno
  }

  # ---- .extractBlockSharded (pecotmr R/genotypeIo.R)
  .extractBlockSharded <- function(handle, snpIdx, meanImpute = TRUE) {
    sampleIds <- handle@sampleIds
    if (length(snpIdx) == 0L) {
      empty <- matrix(numeric(0), nrow = 0L, ncol = length(sampleIds),
                      dimnames = list(character(0), sampleIds))
      return(SummarizedExperiment(
        assays = list(dosage = empty),
        rowRanges = GRanges(),
        colData = DataFrame(sampleId = sampleIds, row.names = sampleIds)))
    }
  
    unifiedChr <- canonChrom(handle@snpInfo$CHR)
    reqChr <- unifiedChr[snpIdx]
    groups <- split(seq_along(snpIdx), reqChr)
  
    ses <- mapply(.extractBlockForChrom, names(groups), groups,
                  MoreArgs = list(handle = handle, snpIdx = snpIdx,
                                  unifiedChr = unifiedChr, meanImpute = meanImpute),
                  SIMPLIFY = FALSE)
    if (length(ses) == 1L) return(ses[[1L]])
  
    # Combine at the assay/rowRanges level (rather than rbind-ing the SEs, which
    # trips on disjoint seqlevels) and restore the requested snpIdx order.
    ord <- order(unlist(groups, use.names = FALSE))
    combinedDos <- do.call(rbind, lapply(ses, function(se)
      SummarizedExperiment::assay(se, "dosage")))[ord, , drop = FALSE]
    combinedGr <- suppressWarnings(
      do.call(c, unname(lapply(ses, SummarizedExperiment::rowRanges))))[ord]
    SummarizedExperiment(
      assays    = list(dosage = combinedDos),
      rowRanges = combinedGr,
      colData   = SummarizedExperiment::colData(ses[[1L]]))
  }

  # ---- .extractBlockVcf (pecotmr R/genotypeIo.R)
  .extractBlockVcf <- function(handle, snpIdx) {
    si <- getSnpInfo(handle)[snpIdx, ]
    gr <- GRanges(
      seqnames = si$CHR,
      ranges = IRanges(start = si$BP, end = si$BP)
    )
    param <- VariantAnnotation::ScanVcfParam(which = gr, fixed = NA,
                                              info = NA, geno = "GT")
    vcf <- VariantAnnotation::readVcf(.genotypeReadPath(handle), genome = "", param = param)
    gt <- VariantAnnotation::geno(vcf)$GT
  
    # Convert GT strings to ALT dosage (A1 dosage)
    geno <- matrix(NA_real_, nrow = ncol(gt), ncol = nrow(gt))
    for (j in seq_len(nrow(gt))) {
      g <- gt[j, ]
      geno[, j] <- vapply(g, function(x) {
        if (is.na(x) || x == "./.") return(NA_real_)
        alleles <- strsplit(x, "[/|]")[[1]]
        sum(alleles != "0")
      }, numeric(1))
    }
  
    geno
  }

  # ---- .findValidFilePath (pecotmr R/ld.R)
  .findValidFilePath <- function(referenceFilePath, targetFilePath) {
    if (file.exists(targetFilePath)) return(targetFilePath)
    targetFullPath <- file.path(dirname(referenceFilePath), targetFilePath)
    if (file.exists(targetFullPath)) return(targetFullPath)
    if (file.exists(referenceFilePath)) return(referenceFilePath)
    stop(sprintf(
      "Both reference and target file paths do not work. Tried paths: '%s' and '%s'",
      referenceFilePath, targetFullPath))
  }

  # ---- .findValidFilePaths (pecotmr R/ld.R)
  .findValidFilePaths <- function(referenceFilePath, targetFilePaths)
    sapply(targetFilePaths, function(x) .findValidFilePath(referenceFilePath, x))

  # ---- .genotypeChromPaths (pecotmr R/GenotypeHandle.R)
  .genotypeChromPaths <- function(handle) {
    tryCatch(handle@chromPaths, error = function(e) character(0))
  }

  # ---- .genotypeReadPath (pecotmr R/GenotypeHandle.R)
  .genotypeReadPath <- function(handle) {
    .resolveGenotypeResourcePath(getPath(handle))
  }

  # ---- .meanImputeGeno (pecotmr R/genotypeIo.R)
  .meanImputeGeno <- function(geno) {
    naCols <- which(colSums(is.na(geno)) > 0L)
    for (j in naCols) {
      colMean <- mean(geno[, j], na.rm = TRUE)
      geno[is.na(geno[, j]), j] <- colMean
    }
    geno
  }

  # ---- .regionToSnpIdx (pecotmr R/genotypeIo.R)
  .regionToSnpIdx <- function(snpInfo, region) {
    parsed <- parseRegion(region)
    chrMatch <- stripChrPrefix(as.character(snpInfo$CHR)) == parsed$chrom
    posMatch <- snpInfo$BP >= parsed$start & snpInfo$BP <= parsed$end
    which(chrMatch & posMatch)
  }

  # ---- .resolveGenotypeResourcePath (pecotmr R/GenotypeHandle.R)
  .resolveGenotypeResourcePath <- function(path) {
    if (length(path) != 1L || is.na(path)) return(path)
    m <- regmatches(path, regexec("^pecotmr://extdata/(.+)$", path))[[1L]]
    if (length(m) != 2L) return(path)
    stem <- m[[2L]]
    bed <- system.file("extdata", paste0(stem, ".bed"), package = "pecotmr")
    if (nzchar(bed)) return(sub("\\.bed$", "", bed))
    resolved <- system.file("extdata", stem, package = "pecotmr")
    if (!nzchar(resolved))
      stop("cannot resolve bundled genotype resource '", stem,
           "' under inst/extdata/ (package 'pecotmr').")
    resolved
  }

  # ---- .snpInfoToVariantInfo (pecotmr R/genotypeIo.R)
  .snpInfoToVariantInfo <- function(snpInfo) {
    data.frame(
      chrom = snpInfo$CHR,
      id = snpInfo$SNP,
      pos = snpInfo$BP,
      A2 = snpInfo$A2,
      A1 = snpInfo$A1,
      stringsAsFactors = FALSE
    )
  }

  # ---- .withGds (pecotmr R/genotypeIo.R)
  .withGds <- function(path, fn, readonly = TRUE, allow.fork = FALSE) {
    gds <- SNPRelate::snpgdsOpen(path, readonly = readonly, allow.fork = allow.fork)
    on.exit(SNPRelate::snpgdsClose(gds))
    fn(gds)
  }

  # ---- canonChrom (pecotmr R/variantId.R)
  canonChrom <- function(x) {
    x <- as.character(x)
    x <- sub("^chr", "", x, ignore.case = TRUE)
    x <- sub("^ch", "", x, ignore.case = TRUE)
    x <- toupper(x)
    ok <- !is.na(x)
    x[ok & x == "23"] <- "X"
    x[ok & x == "24"] <- "Y"
    x[ok & x == "M"] <- "MT"
    x
  }

  # ---- chromOrder (pecotmr R/variantId.R)
  chromOrder <- function(x) {
    x <- canonChrom(x)
    standard <- c(as.character(1:22), "X", "Y", "XY", "MT")
    extra <- setdiff(unique(x[!is.na(x)]), standard)
    factor(x, levels = c(standard, extra), ordered = TRUE)
  }

  # ---- detectVariantConvention (pecotmr R/variantId.R)
  detectVariantConvention <- function(ids) {
    # Find first non-NA element
    firstId <- ids[!is.na(ids)][1]
    if (is.na(firstId) || length(firstId) == 0) {
      return(list(hasChr = FALSE, alleleSep = ":", hasBuild = FALSE, example = NA_character_))
    }
    hasChr <- grepl("^chr", firstId)
    # Detect build suffix like :b38 or _b38 at end
    hasBuild <- grepl("(:|_)b[0-9]+$", firstId)
    idClean <- stripBuildSuffix(firstId)
    # Detect allele separator: check if variant uses underscores between allele fields
    # This catches both full underscore ("1_100_A_G") and mixed ("chr1:100_A_G") formats
    alleleSep <- if (grepl("_[ATCGID*]+_[ATCGID*]+$", idClean)) "_" else ":"
    list(hasChr = hasChr, alleleSep = alleleSep, hasBuild = hasBuild, example = firstId)
  }

  # ---- extractBlockGenotypes (pecotmr R/genotypeIo.R)
  extractBlockGenotypes <- function(handle, snpIdx, meanImpute = TRUE) {
    # One-file-per-chromosome handle: route by chromosome to the right file.
    # `.genotypeChromPaths` tolerates handles deserialized before the slot
    # existed (treated as single-file).
    if (length(.genotypeChromPaths(handle)) > 0L) {
      return(.extractBlockSharded(handle, snpIdx, meanImpute = meanImpute))
    }
    fmt <- getFormat(handle)
    geno <- switch(fmt,
      "gds" = .extractBlockGds(handle, snpIdx),
      "vcf" = .extractBlockVcf(handle, snpIdx),
      "plink1" = .extractBlockPlink1(handle, snpIdx),
      "plink2" = .extractBlockPlink2(handle, snpIdx),
      stop("Unsupported format in extractBlockGenotypes: ", fmt)
    )
    if (is.null(geno)) return(NULL)
    if (meanImpute) geno <- .meanImputeGeno(geno)
  
    # geno is samples x variants from the format extractors
    si <- getSnpInfo(handle)[snpIdx, , drop = FALSE]
    chr <- as.character(si$CHR)
    chr <- sub("^chr", "", chr, ignore.case = TRUE)
    chr <- paste0("chr", chr)
  
    rowRanges <- GRanges(
      seqnames = chr,
      ranges = IRanges(start = as.integer(si$BP), width = 1L)
    )
    mcols(rowRanges) <- DataFrame(
      SNP = si$SNP, A1 = si$A1, A2 = si$A2
    )
  
    sampleIds <- getSampleIds(handle)
    colData <- DataFrame(
      sampleId = sampleIds,
      row.names = sampleIds
    )
  
    # Transpose to Bioc convention: variants x samples
    dosage <- t(geno)
    rownames(dosage) <- si$SNP
    colnames(dosage) <- sampleIds
  
    SummarizedExperiment(
      assays = list(dosage = dosage),
      rowRanges = rowRanges,
      colData = colData
    )
  }

  # ---- extractFilePaths (pecotmr R/ld.R)
  extractFilePaths <- function(genomicData, intersectionRows, columnToExtract) {
    if (!columnToExtract %in% names(genomicData)) {
      stop("Column '", columnToExtract, "' not found in genomic data.")
    }
    idx <- which(genomicData$chrom == intersectionRows$startRow$chrom &
                 genomicData$start >= intersectionRows$startRow$start &
                 genomicData$start <= intersectionRows$endRow$start)
    genomicData[[columnToExtract]][idx]
  }

  # ---- filterVariantsByLdReference (pecotmr R/ld.R)
  filterVariantsByLdReference <- function(variantIds, ldReferenceMetaFile, keepIndel = TRUE) {
    variantsDf <- parseVariantId(variantIds)
  
    # Derive region to scope the reference lookup
    regionDf <- variantsDf %>%
      group_by(chrom) %>%
      summarise(start = min(pos), end = max(pos))
  
    # Use shared helper -- no genotype loading
    refInfo <- getRefVariantInfo(ldReferenceMetaFile, regionDf)
    refChrom <- canonChrom(refInfo$chrom)
    refKey <- paste0(refChrom, ":", refInfo$pos)
  
    variantKey <- paste0(variantsDf$chrom, ":", variantsDf$pos)
    keepIndices <- which(variantKey %in% refKey)
  
    if (!keepIndel) {
      snpIdx <- which(isSnpAlleles(variantsDf$A1, variantsDf$A2))
      keepIndices <- intersect(keepIndices, snpIdx)
    }
  
    nDropped <- length(variantIds) - length(keepIndices)
    if (nDropped > 0) {
      message(nDropped, " out of ", length(variantIds),
              " total variants dropped due to absence on the reference LD panel.")
    }
  
    list(data = variantIds[keepIndices], idx = keepIndices)
  }

  # ---- findIntersectionRows (pecotmr R/ld.R)
  findIntersectionRows <- function(genomicData, regionChrom, regionStart, regionEnd) {
    chromData <- genomicData %>% filter(chrom == regionChrom)
    if (nrow(chromData) == 0) stop("No data for chromosome ", regionChrom)
  
    # Clamp query to available range
    regionStart <- max(regionStart, min(chromData$start))
    regionEnd   <- min(regionEnd,   max(chromData$end))
  
    startRow <- genomicData %>%
      filter(chrom == regionChrom, start <= regionStart, end > regionStart) %>%
      slice(1)
    endRow <- genomicData %>%
      filter(chrom == regionChrom, start < regionEnd, end >= regionEnd) %>%
      arrange(desc(end)) %>%
      slice(1)
  
    if (nrow(startRow) == 0 || nrow(endRow) == 0) {
      stop("Region ", regionChrom, ":", regionStart, "-", regionEnd,
           " is not covered by any rows in the LD metadata.")
    }
    list(startRow = startRow, endRow = endRow)
  }

  # ---- findStochasticMeta (pecotmr R/genotypeIo.R)
  findStochasticMeta <- function(genotypePath) {
    # Strip known genotype extensions to get the stem
    stem <- sub("\\.(vcf|vcf\\.gz|bcf|gds|bed|bim|fam|pgen|pvar|psam)$", "",
                genotypePath)
    candidates <- c(
      paste0(stem, ".afreq"),
      paste0(stem, ".afreq.zst"),
      paste0(stem, ".stochastic_meta.tsv")
    )
    found <- candidates[file.exists(candidates)]
    if (length(found) > 0) found[1] else NULL
  }

  # ---- formatVariantId (pecotmr R/variantId.R)
  formatVariantId <- function(chrom, pos, A2, A1, chrPrefix = TRUE, alleleSep = ":", convention = NULL) {
    # If convention is provided, use it to determine format automatically
    if (!is.null(convention)) {
      chrPrefix <- convention$hasChr
      alleleSep <- if (!is.null(convention$alleleSep)) convention$alleleSep else ":"
    }
    # Normalize the chromosome (strip prefix, uppercase, map synonyms) then re-add
    # the "chr" prefix if requested. canonChrom keeps X/Y/MT as strings.
    chromClean <- canonChrom(chrom)
    if (chrPrefix) {
      paste0("chr", chromClean, ":", pos, alleleSep, A2, alleleSep, A1)
    } else {
      paste0(chromClean, ":", pos, alleleSep, A2, alleleSep, A1)
    }
  }

  # ---- getRefVariantInfo (pecotmr R/genotypeIo.R)
  getRefVariantInfo <- function(source, region = NULL) {
    resolved <- resolveLdSource(source)
  
    # For genotype sources via metadata, resolve per-chromosome path
    if (resolved$type %in% c("plink2", "plink1", "vcf", "gds") && !is.null(resolved$metaPath) && !is.null(region)) {
      dataPath <- resolveGenotypePathForRegion(resolved$metaPath, region)
    } else {
      dataPath <- resolved$dataPath
    }
  
    if (resolved$type == "plink2") {
      paths <- resolvePlink2Paths(dataPath)
      info <- readPvar(paths$pvar)
      afreq <- readAfreq(dataPath)
      if (!is.null(afreq)) {
        info$allele_freq <- afreq$alt_freq[match(info$id, afreq$id)]
      }
    } else if (resolved$type == "plink1") {
      bim <- readBim(paste0(dataPath, ".bed"))
      info <- data.frame(
        chrom = bim$chrom, id = bim$id, pos = bim$pos,
        A2 = bim$a0, A1 = bim$a1,
        stringsAsFactors = FALSE
      )
    } else if (resolved$type %in% c("vcf", "gds")) {
      # VCF/GDS: load via the genotype loader and extract variant_info
      result <- loadGenotypeRegion(dataPath, region = region,
                                   returnVariantInfo = TRUE)
      info <- result$variant_info
      # Compute allele frequency from the genotype matrix
      info$allele_freq <- colMeans(result$X, na.rm = TRUE) / 2
      return(info)  # Already region-filtered by the loader
    } else {
      # Pre-computed LD: read bim/pvar files via metadata
      bimPaths <- getRegionalLdMeta(resolved$metaPath, region)$intersections$bimFilePaths
      info <- do.call(rbind, lapply(bimPaths, function(path) {
        df <- readVariantMetadata(path)
        out <- data.frame(
          chrom = df$chrom, id = df$id, pos = df$pos,
          A2 = df$A2, A1 = df$A1,
          stringsAsFactors = FALSE
        )
        if ("variance" %in% names(df)) out$variance <- df$variance
        if ("allele_freq" %in% names(df)) out$allele_freq <- df$allele_freq
        if ("n_nomiss" %in% names(df)) out$n_nomiss <- df$n_nomiss
        out
      }))
      info$id <- normalizeVariantId(info$id)
      return(info)  # Already region-filtered by getRegionalLdMeta
    }
  
    # Region filter for plink2/plink1
    if (!is.null(region)) {
      parsed <- parseRegion(region)
      infoChrom <- stripChrPrefix(info$chrom)
      # Handle multi-row region data.frame (one row per chrom)
      if (is.data.frame(parsed) && nrow(parsed) > 1) {
        inRegion <- rep(FALSE, nrow(info))
        for (r in seq_len(nrow(parsed))) {
          inRegion <- inRegion | (infoChrom == as.character(parsed$chrom[r]) &
                                  info$pos >= parsed$start[r] & info$pos <= parsed$end[r])
        }
      } else {
        inRegion <- infoChrom == as.character(parsed$chrom) &
                    info$pos >= parsed$start & info$pos <= parsed$end
      }
      info <- info[inRegion, , drop = FALSE]
    }
    info
  }

  # ---- getRegionalLdMeta (pecotmr R/ld.R)
  getRegionalLdMeta <- function(ldReferenceMetaFile, region, completeCoverageRequired = FALSE) {
    genomicData <- vroom(ldReferenceMetaFile)
    region <- parseRegion(region)
    # Set column names
    names(genomicData) <- c("chrom", "start", "end", "path")
    names(region) <- c("chrom", "start", "end")
  
    # Treat start=0, end=0 as "covers all regions" (used for whole-chromosome PLINK files)
    wholeChrom <- genomicData$start == 0 & genomicData$end == 0
    if (any(wholeChrom)) genomicData$end[wholeChrom] <- Inf
  
    # Order and deduplicate regions
    genomicData <- orderDedupRegions(genomicData)
    region <- orderDedupRegions(region)
  
    # Process file paths
    filePath <- genomicData$path %>%
      str_split(",", simplify = TRUE) %>%
      data.frame() %>%
      `colnames<-`(if (ncol(.) == 2) c("LD_file_path", "bim_file_path") else c("LD_file_path"))
  
    genomicData <- cbind(genomicData, filePath) %>% select(-path)
  
    # Find intersection rows
    intersectionRows <- findIntersectionRows(genomicData, region$chrom, region$start, region$end)
  
    # Validate region
    if (completeCoverageRequired) {
      validateSelectedRegion(intersectionRows$startRow, intersectionRows$endRow, region$start, region$end)
    }
  
    # Extract file paths
    ldPaths <- .findValidFilePaths(ldReferenceMetaFile, extractFilePaths(genomicData, intersectionRows, "LD_file_path"))
    bimPaths <- if ("bim_file_path" %in% names(genomicData)) {
      .findValidFilePaths(ldReferenceMetaFile, extractFilePaths(genomicData, intersectionRows, "bim_file_path"))
    } else {
      NULL
    }
  
    return(list(
      intersections = list(
        startIndex = intersectionRows$startRow,
        endIndex = intersectionRows$endRow,
        LD_file_paths = ldPaths,
        bimFilePaths = bimPaths
      ),
      ldMetaData = genomicData,
      region = region
    ))
  }

  # ---- hasPlink1Files (pecotmr R/ld.R)
  hasPlink1Files <- function(prefix) {
    file.exists(paste0(prefix, ".bed")) &&
      file.exists(paste0(prefix, ".bim")) &&
      file.exists(paste0(prefix, ".fam"))
  }

  # ---- hasPlink2Files (pecotmr R/ld.R)
  hasPlink2Files <- function(prefix) {
    file.exists(paste0(prefix, ".pgen")) &&
      (file.exists(paste0(prefix, ".pvar")) || file.exists(paste0(prefix, ".pvar.zst"))) &&
      file.exists(paste0(prefix, ".psam"))
  }

  # ---- invertMinmaxScaling (pecotmr R/genotypeIo.R)
  invertMinmaxScaling <- function(X, uMin, uMax) {
    if (length(uMin) != ncol(X) || length(uMax) != ncol(X)) {
      stop("Length of u_min/u_max (", length(uMin), ") must equal ncol(X) (", ncol(X), ")")
    }
    denom <- uMax - uMin
    denom[denom == 0] <- 1  # monomorphic: scaling was identity
    # Invert: U_original = U_scaled * (u_max - u_min) / 2 + u_min
    sweep(sweep(X, 2, denom / 2, "*"), 2, uMin, "+")
  }

  # ---- isGdsPath (pecotmr R/ld.R)
  isGdsPath <- function(path) {
    grepl("\\.gds$", path) && file.exists(path)
  }

  # ---- isSnpAlleles (pecotmr R/variantId.R)
  isSnpAlleles <- function(a1, a2) {
    nchar(a1) == 1L & nchar(a2) == 1L &
      grepl("^[ATCG]$", a1) & grepl("^[ATCG]$", a2)
  }

  # ---- isVcfPath (pecotmr R/ld.R)
  isVcfPath <- function(path) {
    grepl("\\.(vcf|vcf\\.gz|bcf)$", path) && file.exists(path)
  }

  # ---- loadGenotypeRegion (pecotmr R/genotypeIo.R)
  loadGenotypeRegion <- function(genotype, region = NULL, keepIndel = TRUE,
                                 keepVariantsPath = NULL,
                                 returnVariantInfo = FALSE,
                                 stochasticMetaPath = NULL,
                                 stochasticMetaFormat = NULL) {
    # --- Detect format and create GenotypeHandle ---
    if (grepl("\\.(vcf|vcf\\.gz|bcf)$", genotype)) {
      handle <- readGenotypes(genotype, format = "vcf")
    } else if (grepl("\\.gds$", genotype)) {
      handle <- readGenotypes(genotype, format = "gds")
    } else if (hasPlink2Files(genotype)) {
      handle <- readGenotypes(genotype, format = "plink2")
    } else if (hasPlink1Files(genotype)) {
      handle <- readGenotypes(genotype, format = "plink1")
    } else {
      stop("Genotype files not found at: ", genotype,
           "\n  Expected: .vcf/.vcf.gz/.bcf, .gds, or PLINK prefix (.pgen/.pvar[.zst]/.psam or .bed/.bim/.fam)")
    }
  
    # --- Region filter ---
    handleSnpInfo <- getSnpInfo(handle)
    if (!is.null(region)) {
      snpIdx <- .regionToSnpIdx(handleSnpInfo, region)
      if (length(snpIdx) == 0) {
        stop(NoSnpsError(paste("No SNPs found in the specified region", region)))
      }
    } else {
      snpIdx <- seq_len(nrow(handleSnpInfo))
    }
  
    # --- Extract genotypes (no mean imputation — callers handle missing) ---
    # Samples x variants matrix (pecotmr convention); callers handle missing.
    X <- .dosageMatrix(handle, snpIdx, meanImpute = FALSE)
    variantInfo <- .snpInfoToVariantInfo(
      handleSnpInfo[snpIdx, , drop = FALSE])
  
    # --- Attach allele frequency from .afreq sidecar (plink2 only) ---
    if (getFormat(handle) == "plink2") {
      afreq <- readAfreq(.genotypeReadPath(handle))
      if (!is.null(afreq)) {
        afreqCols <- intersect(c("id", "alt_freq", "obs_ct"), colnames(afreq))
        variantInfo <- merge(variantInfo, afreq[, afreqCols, drop = FALSE],
                             by = "id", all.x = TRUE, sort = FALSE)
      }
    }
  
    result <- list(X = X, variant_info = variantInfo)
  
    # --- Post-filters: indels and variant whitelist ---
    if (!keepIndel) {
      snpMask <- isSnpAlleles(result$variant_info$A1, result$variant_info$A2)
      result$X <- result$X[, snpMask, drop = FALSE]
      result$variant_info <- result$variant_info[snpMask, , drop = FALSE]
    }
    if (!is.null(keepVariantsPath)) {
      keepIdx <- matchVariantsToKeep(result$variant_info, keepVariantsPath)
      result$X <- result$X[, keepIdx, drop = FALSE]
      result$variant_info <- result$variant_info[keepIdx, , drop = FALSE]
    }
  
    # --- Detect and invert stochastic genotype scaling ---
    metaPath <- stochasticMetaPath %||% findStochasticMeta(genotype)
    if (!is.null(metaPath)) {
      smeta <- readStochasticMeta(metaPath, format = stochasticMetaFormat)
      if (!is.null(smeta)) {
        idx <- match(colnames(result$X), smeta$id)
        matched <- !is.na(idx)
        if (any(matched)) {
          result$X[, matched] <- invertMinmaxScaling(
            result$X[, matched, drop = FALSE],
            smeta$u_min[idx[matched]],
            smeta$u_max[idx[matched]]
          )
          result$variant_info$u_min <- smeta$u_min[idx]
          result$variant_info$u_max <- smeta$u_max[idx]
          message("Stochastic genotype detected: restored original scale via ", basename(metaPath))
        }
      }
    } else {
      isStochastic <- !all(result$X == round(result$X), na.rm = TRUE)
      if (isStochastic) {
        warning("Non-integer genotype values detected but no stochastic metadata sidecar found. ",
                "Place a .afreq or .stochastic_meta.tsv file with u_min/u_max columns ",
                "alongside the genotype files to restore the original scale.")
      }
    }
  
    if (returnVariantInfo) result else result$X
  }

  # ---- matchVariantsToKeep (pecotmr R/genotypeIo.R)
  matchVariantsToKeep <- function(variantInfo, keepVariantsPath) {
    keepRaw <- tryCatch(
      as.data.frame(vroom(keepVariantsPath, show_col_types = FALSE)),
      error = function(e) NULL
    )
    if (!is.null(keepRaw) && "chrom" %in% names(keepRaw) && "pos" %in% names(keepRaw)) {
      keepVariants <- parseVariantId(keepRaw)
    } else {
      # Fall back to reading as single-column variant IDs
      ids <- read_lines(keepVariantsPath)
      keepVariants <- parseVariantId(ids)
    }
    viChrom <- canonChrom(variantInfo$chrom)
    hasAlleles <- "A1" %in% names(keepVariants) && "A2" %in% names(keepVariants) &&
      !any(is.na(keepVariants$A1)) && !any(is.na(keepVariants$A2))
    if (hasAlleles) {
      paste0(viChrom, ":", variantInfo$pos, ":", variantInfo$A2, ":", variantInfo$A1) %in%
        paste0(keepVariants$chrom, ":", keepVariants$pos, ":", keepVariants$A2, ":", keepVariants$A1)
    } else {
      paste0(viChrom, ":", variantInfo$pos) %in%
        paste0(keepVariants$chrom, ":", keepVariants$pos)
    }
  }

  # ---- normalizeVariantId (pecotmr R/variantId.R)
  normalizeVariantId <- function(ids, chrPrefix = TRUE, convention = NULL) {
    parsed <- parseVariantId(ids)
    out <- as.character(ids)
    # Only re-format ids that parsed into a chrom + pos; leave unparseable ids
    # (e.g. rsIDs) unchanged rather than emitting "chrNA:..." garbage.
    ok <- !is.na(parsed$chrom) & !is.na(parsed$pos)
    if (any(ok)) {
      out[ok] <- if (!is.null(convention))
        formatVariantId(parsed$chrom[ok], parsed$pos[ok], parsed$A2[ok],
                        parsed$A1[ok], convention = convention)
      else
        formatVariantId(parsed$chrom[ok], parsed$pos[ok], parsed$A2[ok],
                        parsed$A1[ok], chrPrefix = chrPrefix)
    }
    out
  }

  # ---- NoSnpsError (pecotmr R/genotypeIo.R)
  NoSnpsError <- function(message) {
    structure(list(message = message), class = c("NoSnpsError", "error", "condition"))
  }

  # ---- orderDedupRegions (pecotmr R/ld.R)
  orderDedupRegions <- function(df) {
    df$chrom <- canonChrom(df$chrom)
    df <- distinct(df, chrom, start, .keep_all = TRUE) %>%
      arrange(chromOrder(chrom), start)
    df
  }

  # ---- parseRegion (pecotmr R/variantId.R)
  parseRegion <- function(region) {
    if (!is.character(region) || length(region) != 1) {
      return(region)
    }
  
    if (!grepl("^chr[0-9XY]+:[0-9]+-[0-9]+$", region)) {
      stop("Input string format must be 'chr:start-end'.")
    }
    parts <- str_split(region, "[:-]")[[1]]
    df <- data.frame(
      chrom = canonChrom(parts[1]),
      start = as.integer(parts[2]),
      end = as.integer(parts[3])
    )
  
    return(df)
  }

  # ---- parseVariantId (pecotmr R/variantId.R)
  parseVariantId <- function(ids) {
    # Handle data.frame input
    if (is.data.frame(ids)) {
      if (all(c("chrom", "pos", "A2", "A1") %in% names(ids))) {
        # Already has correct column names
      } else if (all(c("chrom", "pos", "A1", "A2") %in% names(ids))) {
        # Has A1/A2 but need to check they're in the right semantic order
        # (A2 = ref, A1 = alt/effect) -- keep as-is since column names are explicit
      } else if (ncol(ids) >= 4) {
        # Assume positional: chrom, pos, A2, A1
        names(ids)[1:4] <- c("chrom", "pos", "A2", "A1")
      }
      # Detect convention from chrom column before converting
      conv <- list(
        hasChr = any(grepl("^chr", as.character(ids$chrom))),
        alleleSep = ":", hasBuild = FALSE, example = NA_character_
      )
      ids$chrom <- canonChrom(ids$chrom)
      ids$pos <- as.integer(ids$pos)
      attr(ids, "convention") <- conv
      return(ids)
    }
  
    # Detect convention before parsing
    convention <- detectVariantConvention(ids)
  
    # Normalize: convert underscores to colons, strip build suffix
    normalized <- gsub("_", ":", ids)
    normalized <- stripBuildSuffix(normalized)
  
    # Split into exactly 4 fields using strcapture (vectorized, no list overhead)
    data <- strcapture(
      "^([^:]+):([^:]+):([^:]+):([^:]+)",
      normalized,
      proto = data.frame(chrom = character(), pos = character(),
                         A2 = character(), A1 = character(),
                         stringsAsFactors = FALSE)
    )
  
    data$chrom <- canonChrom(data$chrom)
    data$pos <- as.integer(data$pos)
  
    attr(data, "convention") <- convention
    return(data)
  }

  # ---- readAfreq (pecotmr R/genotypeIo.R)
  readAfreq <- function(prefix) {
    afreqZst <- paste0(prefix, ".afreq.zst")
    afreqPlain <- paste0(prefix, ".afreq")
    if (file.exists(afreqZst)) {
      if (Sys.which("zstd") == "") stop("zstd CLI is required to read .afreq.zst files")
      af <- as.data.frame(vroom(pipe(paste0("zstd -dcq ", shQuote(afreqZst))),
                                delim = "\t", show_col_types = FALSE))
    } else if (file.exists(afreqPlain)) {
      af <- as.data.frame(vroom(afreqPlain, delim = "\t", show_col_types = FALSE))
    } else {
      return(NULL)
    }
    # PLINK2 .afreq: REF = A2, ALT = A1, ALT_FREQS = A1 (effect allele) frequency
    af <- rename(af,
      "chrom" = "#CHROM", "id" = "ID",
      "A2" = "REF", "A1" = "ALT",
      "alt_freq" = "ALT_FREQS", "obs_ct" = "OBS_CT"
    )
    cols <- c("chrom", "id", "A2", "A1", "alt_freq", "obs_ct")
    # Stochastic genotype .afreq includes U_MIN/U_MAX for exact min-max inversion
    if ("U_MIN" %in% colnames(af)) {
      af <- rename(af, "u_min" = "U_MIN", "u_max" = "U_MAX")
      cols <- c(cols, "u_min", "u_max")
    }
    af <- select(af, all_of(cols))
    return(af)
  }

  # ---- readBim (pecotmr R/genotypeIo.R)
  readBim <- function(bed) {
    bimf <- paste0(file_path_sans_ext(bed), ".bim")
    bim <- vroom(bimf, col_names = FALSE)
    colnames(bim) <- c("chrom", "id", "gpos", "pos", "a1", "a0")
    return(bim)
  }

  # ---- readPvar (pecotmr R/genotypeIo.R)
  readPvar <- function(pvarPath) {
    if (!requireNamespace("pgenlibr", quietly = TRUE)) {
      # nocov start
      stop("pgenlibr is required. Install from https://cran.r-project.org/web/packages/pgenlibr/index.html")
      # nocov end
    }
    pvar <- pgenlibr::NewPvar(pvarPath)
    on.exit(pgenlibr::ClosePvar(pvar), add = TRUE)
    n <- pgenlibr::GetVariantCt(pvar)
    idx <- seq_len(n)
    data.frame(
      chrom = vapply(idx, function(i) pgenlibr::GetVariantChrom(pvar, i), character(1)),
      id    = vapply(idx, function(i) pgenlibr::GetVariantId(pvar, i), character(1)),
      pos   = vapply(idx, function(i) pgenlibr::GetVariantPos(pvar, i), integer(1)),
      A2    = vapply(idx, function(i) pgenlibr::GetAlleleCode(pvar, i, 1L), character(1)),
      A1    = vapply(idx, function(i) pgenlibr::GetAlleleCode(pvar, i, 2L), character(1)),
      stringsAsFactors = FALSE
    )
  }

  # ---- readStochasticMeta (pecotmr R/genotypeIo.R)
  readStochasticMeta <- function(path, format = NULL) {
    if (!file.exists(path)) return(NULL)
  
    if (is.null(format)) {
      format <- if (grepl("\\.afreq(\\.zst)?$", path)) "afreq" else "generic"
    }
    format <- match.arg(format, c("afreq", "generic"))
  
    if (format == "afreq") {
      # readAfreq expects a prefix, not a full path - strip the .afreq[.zst] suffix
      prefix <- sub("\\.afreq(\\.zst)?$", "", path)
      af <- readAfreq(prefix)
      if (is.null(af) || !all(c("u_min", "u_max") %in% colnames(af))) return(NULL)
      return(af[, c("id", "u_min", "u_max"), drop = FALSE])
    }
  
    # Generic: expect tab-delimited with columns id, u_min, u_max
    meta <- as.data.frame(vroom(path, delim = "\t", show_col_types = FALSE))
    required <- c("id", "u_min", "u_max")
    if (!all(required %in% colnames(meta))) {
      stop("Stochastic metadata file '", path, "' must contain columns: ",
           paste(required, collapse = ", "))
    }
    meta[, required, drop = FALSE]
  }

  # ---- readVariantMetadata (pecotmr R/genotypeIo.R)
  readVariantMetadata <- function(snpFilePath) {
    isPvar <- grepl("\\.(pvar|pvar\\.zst)$", snpFilePath)
    if (!isPvar) {
      firstLine <- readLines(snpFilePath, n = 1)
      isPvar <- grepl("^#CHROM", firstLine)
    }
  
    if (isPvar) {
      readPvar(snpFilePath)
    } else {
      df <- read.table(snpFilePath, stringsAsFactors = FALSE)
      n <- ncol(df)
      if (n == 6) {
        names(df) <- c("chrom", "id", "gpos", "pos", "A1", "A2")
      } else if (n == 9) {
        names(df) <- c("chrom", "id", "gpos", "pos", "A1", "A2", "variance", "allele_freq", "n_nomiss")
      } else {
        stop("Unexpected number of columns (", n, ") in variant file: ", snpFilePath)
      }
      df
    }
  }

  # ---- resolveGenotypePathForRegion (pecotmr R/ld.R)
  resolveGenotypePathForRegion <- function(metaPath, region) {
    parsed <- parseRegion(region)
    meta <- as.data.frame(vroom(metaPath, show_col_types = FALSE))
    colnames(meta) <- c("chrom", "start", "end", "path")
    meta$chrom <- canonChrom(meta$chrom)
    queryChrom <- canonChrom(parsed$chrom)
  
    matching <- meta[meta$chrom == queryChrom, , drop = FALSE]
    if (nrow(matching) == 0) {
      stop("No entry for chromosome ", queryChrom, " in metadata file: ", metaPath)
    }
    rawPath <- gsub(",.*$", "", matching$path[1])
    file.path(dirname(metaPath), rawPath)
  }

  # ---- resolveLdSource (pecotmr R/ld.R)
  resolveLdSource <- function(path) {
    if (!file.exists(path)) {
      stop("LD metadata file not found: ", path,
           "\n  Expected: a TSV file with columns chrom, start, end, path.")
    }
  
    # Peek at first row to determine underlying data type
    meta <- as.data.frame(vroom(path, show_col_types = FALSE, n_max = 1))
    if (ncol(meta) < 4) stop("LD metadata file must have at least 4 columns (chrom, start, end, path): ", path)
    colnames(meta)[1:4] <- c("chrom", "start", "end", "path")
    rawPath <- gsub(",.*$", "", meta$path[1])  # strip comma-separated bim path
    resolved <- file.path(dirname(path), rawPath)
  
    if (hasPlink2Files(resolved)) return(list(type = "plink2", dataPath = resolved, metaPath = path))
    if (hasPlink1Files(resolved)) return(list(type = "plink1", dataPath = resolved, metaPath = path))
    if (isVcfPath(resolved)) return(list(type = "vcf", dataPath = resolved, metaPath = path))
    if (isGdsPath(resolved)) return(list(type = "gds", dataPath = resolved, metaPath = path))
  
    # Pre-computed .cor.xz blocks - verify not using 0:0 sentinel
    if (!is.na(meta$start) && !is.na(meta$end) && meta$start == 0 && meta$end == 0) {
      stop("Metadata has start=0, end=0 but path does not resolve to genotype files: ", resolved,
           "\n  The 0:0 sentinel is only valid for whole-chromosome genotype files.")
    }
  
    list(type = "precomputed", metaPath = path)
  }

  # ---- resolvePlink2Paths (pecotmr R/genotypeIo.R)
  resolvePlink2Paths <- function(prefix) {
    pgen <- paste0(prefix, ".pgen")
    if (!file.exists(pgen)) {
      stop("PLINK2 .pgen file not found at: ", pgen,
           "\n  Note: .pgen must be uncompressed (plink2 does not compress .pgen).")
    }
    # Prefer plain .pvar (fast, no extra deps); fall back to .pvar.zst
    pvar <- if (file.exists(paste0(prefix, ".pvar"))) {
      paste0(prefix, ".pvar")
    } else if (file.exists(paste0(prefix, ".pvar.zst"))) {
      paste0(prefix, ".pvar.zst")
    } else {
      stop("PLINK2 .pvar[.zst] file not found at prefix: ", prefix)
    }
    psam <- paste0(prefix, ".psam")
    if (!file.exists(psam)) {
      stop("PLINK2 .psam file not found at: ", psam,
           "\n  Note: .psam must be uncompressed (plink2 does not compress .psam).")
    }
    list(pgen = pgen, pvar = pvar, psam = psam)
  }

  # ---- stripBuildSuffix (pecotmr R/variantId.R)
  stripBuildSuffix <- function(x) sub("(:|_)b[0-9]+$", "", x)

  # ---- stripChrPrefix (pecotmr R/variantId.R)
  stripChrPrefix <- function(x) sub("^chr", "", x)

  # ---- validateSelectedRegion (pecotmr R/ld.R)
  validateSelectedRegion <- function(startRow, endRow, regionStart, regionEnd) {
    if (startRow$start > regionStart || endRow$end < regionEnd) {
      stop("Region ", regionStart, "-", regionEnd, " is not fully covered by the LD metadata ",
           "(available: ", startRow$start, "-", endRow$end, ").")
    }
  }

  invisible(NULL)
}

